from common import *
import random
stem="Knox & Clarke 2004 Cunninghamia_primary juvenile period"
t=md(stem)
t1=t.split("**Table 1.")[1].split("### *Primary juvenile")[0]
t2=t.split("**Table 2.")[1].split("and fire intensity). Neither")[0]
def name(c):
    s=c.replace("\\*","")
    s=re.sub(r"\*([^*]+)\*",r"\1",s).strip()
    return s
def split(n):
    w=n.split(); g=w[0]; rest=w[1:]
    sub="";
    for k in ("subsp.","var."):
        if k in rest:
            i=rest.index(k); sub=" ".join(rest[i:]); rest=rest[:i]
    return g," ".join(rest),sub
T1={}
src1={}
for l in t1.splitlines():
    if not l.startswith("|") or "Species" in l or "---" in l: continue
    c=pipe(l); n=name(c[0]); T1[n]=c[1:]; src1[n]=l
rows=[];srcl={}
SRC="Knox, K. J. E., & Clarke, P. J. (2004). Fire response syndromes of shrubs in grassy woodlands in the New England Tableland Bioregion. Cunninghamia, 8(3), 348-353."
paper=("Paper-wide: values are not split by reserve; species not assigned to a reserve, so one row for both reserves (p. 349); "
 "Imbota Nature Reserve: experimental burns in Spring 1999, average yearly rainfall 790 mm (Armidale); Booroolong Nature Reserve: experimental burns in Autumn 2000, average yearly rainfall 884 mm (nearby Guyra, no specific climate data); "
 "coordinates not stated; fire intensity not measured, moderate and low intensity expected in high and low fuel load areas respectively (p. 349); "
 "obligate seeders = less than 30% of individuals survived 100% leaf scorch, resprouters = more than 70% survived (p. 349); "
 "primary and secondary juvenile periods observed in August 2002 and September 2003 at sites 1.5 to 3 years post-fire (p. 350); n.a. and * (no data) cells left empty")
def tv(v):
    v=v.strip()
    if v in("\\*","*"): return None
    m=re.fullmatch(r"Not flowering after ([\d.]+) years",v)
    if m: return ">"+m.group(1)
    m=re.fullmatch(r"< ?([\d.]+) years",v)
    if m: return "<"+m.group(1)
    m=re.fullmatch(r"([\d.]+) years",v); assert m,v
    return m.group(1)
for l in t2.splitlines():
    if not l.startswith("|") or "Species" in l or "---" in l: continue
    c=pipe(l); n=name(c[0]); g,s,sub=split(n)
    r={"Genus":g,"Species":s}
    if sub: r["subsp"]=sub
    r["scientific_name"]=f"{g} {s}"
    fr=c[1]; r["fire_response categorical_surv1"]={"resprouter":"resprouter","obligate seeder":"obligate"}[fr]
    notes=[]
    if n in T1:
        f1,sv,ss,mode=T1[n]; assert f1==fr
        notes.append(f"Table 1, p. 350; Table 2, p. 351")
        if mode!="n.a.": r["resprouter_type"]=mode
        notes.append(f"survival {sv}% (sample size {ss.strip('()')}) in Table 1")
    else:
        notes.append("Table 2, p. 351; species not in Table 1, fire response from Table 2")
    p=tv(c[2]); sj=tv(c[3]) if c[3]!="n.a." else None
    if p: r["primary_juvenile_period"]=p
    if sj: r["secondary_juvenile_period"]=sj; r["Time_unit"]="years"
    if c[2].startswith("Not flow"): notes.append(f"primary_juvenile_period printed as '{c[2]}'")
    if c[3].startswith("Not flow"): notes.append(f"secondary_juvenile_period printed as '{c[3]}'")
    if "<" in c[3]: notes.append(f"secondary_juvenile_period printed as '{c[3]}'")
    if n=="Pultenaea setulosai": notes.append("species name printed as 'setulosai'")
    if n=="Leucopogon sp. nov": notes.append("species printed as 'sp. nov'")
    r.update({"Location_name":"Imbota Nature Reserve; Booroolong Nature Reserve","Fire_type":"experimental burn","Fire_season_categorical":"Spring; Autumn","Fire_severity_categorical":"Low; Moderate"})
    notes.append(paper)
    r["Notes"]="; ".join(notes); r["Source"]=SRC; r["File_name"]=stem
    rows.append(r); srcl[id(r)]=l
print(len(rows),len(T1), set(T1)-{ (r["scientific_name"]+(" "+r["subsp"] if "subsp" in r else "")) for r in rows} and "")
random.seed(5)
for r in random.sample(rows,3):
    print(srcl[id(r)]); print(src1.get(name(srcl[id(r)].split("|")[1]),"")); print({k:v for k,v in r.items() if k not in("Notes","Source","File_name","Location_name")})
import pickle; pickle.dump(rows,open("knox.pkl","wb"))
E
