cd /tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/09907120-2b79-4141-933d-7796f325ad25/scratchpad; cat > kub.py <<'E'
from common import *
import random, pickle
stem="Kubiak Cunn 2009"
t=md(stem); pg=t.split("<!-- PAGE BREAK -->")
SRC="Kubiak, P. J. (2009). Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia, 11(1), 131-165."
LCR,NL,BOTH="Lane Cove River","Narrabeen Lagoon","Lane Cove River; Narrabeen Lagoon"
PAPER=("Paper-wide: wildfires of January 1994 in the Lane Cove River catchment (fire began 6 January 1994, p. 133) and Narrabeen Lagoon catchment (fire began 8 January 1994, p. 134), northern Sydney; "
 "coordinates lat 33° 45' S, long 151° 05' E given for the study area (p. 131); Fire_season_categorical derived from the January fire dates; "
 "Fire_severity_categorical from fires generally described as being of a very high intensity (p. 133), with some patchiness (p. 135-136); "
 "observations Lane Cove River Jan 1994 - Oct 1999 and Narrabeen Lagoon Mar - Oct 1994 (p. 134); fire responses are for plants 100% scorched (p. 136); "
 "fire response codes (p. 145): R = majority of adult plants resprouted (written resprouter), K = majority killed (written obligate), r = a small proportion resprouted, k = a small proportion killed, pR/pK = probably resprouted/killed, ?R/?K = possibly resprouted/killed; "
 "w = weeks, y = years, c. = approximately, bold type = sizable proportion of population flowering, (1) = one plant, shd = shedding seed or spores, grn = green fruit, imm = immature fruit, ri = ripe fruit, buds = flowers in bud, adv = advanced seedlings, m.i.f = moderate intensity fire, "
 "prob.pk.pf.flower./fruit. = probable peak of post-fire flowering/fruiting, poss.pk.pf. = possible peak, * = exotic species; "
 "First fruiting, Seedlings first observed, post-fire peaks and underlined values bridging Resp and Seed are in Notes only; fixed-unit columns convert weeks to years by dividing by 52")
def fmt(x):
    s=f"{x:.3f}".rstrip("0").rstrip("."); return s
def num(s): return float(s)
def clean(s): return s.replace("–","-").replace("—","-")
def parse_time(cell):
    raw=cell.strip()
    if not raw: return None
    if "<u>" in raw: return {"kind":"bridge","raw":raw}
    s=raw.replace("**","")
    m=re.match(r"^At least (\d+) years$",s)
    if m: return {"kind":"val","lo":m.group(1),"hi":None,"unit":"y","gt":">","raw":raw,"simple":False}
    m=re.match(r"^Less than (\d+) year$",s)
    if m: return {"kind":"val","lo":m.group(1),"hi":None,"unit":"y","gt":"<","raw":raw,"simple":False}
    m=re.search(r"flowered (\d+)w after fire",s)
    if m and raw.startswith("Resprouted"): return {"kind":"val","lo":m.group(1),"hi":None,"unit":"w","gt":"","raw":raw,"simple":False}
    m=re.match(r"^\s*(c\.\s*)?(\?)?(\d+(?:\.\d+)?)(?:\s*[–-]\s*(\d+(?:\.\d+)?))?(\+)?\s*([wy])?",s)
    if not m: return {"kind":"text","raw":raw}
    unit=m.group(6)
    if not unit:
        mu=re.search(r"\d\s*([wy])",s)
        unit=mu.group(1) if mu else None
    if not unit: return {"kind":"text","raw":raw}
    simple=bool(re.fullmatch(r"\d+(\.\d+)?[wy]",s))
    return {"kind":"val","lo":m.group(3),"hi":m.group(4),"unit":unit,"gt":">" if m.group(5) else "","raw":raw,"simple":simple}
def to_years(v):
    lo,hi,u,gt=v["lo"],v["hi"],v["unit"],v["gt"]
    if u=="y":
        out=lo+("-"+hi if hi else ""); conv=None
    else:
        out=fmt(num(lo)/52)+("-"+fmt(num(hi)/52) if hi else ""); conv=lo+("-"+hi if hi else "")+" weeks"
    return gt+out, conv
def asis(v): return v["gt"]+v["lo"]+("-"+v["hi"] if v["hi"] else "")

