from common import *
stem="Muir et al 2014 AustJBot_obligate seeder juvenile"
t=md(stem)
t1=t.split("**Table 1.")[1].split("**Table 2.")[0]
t4=t.split("**Table 4.")[1].split("**Fig. 2.")[0]
def nm(c): return re.sub(r"\*","",c).strip()
T4={}
for l in t4.splitlines():
    if l.startswith("|") and "---" not in l and "Species" not in l:
        c=pipe(l); T4[nm(c[0])]=c
sp=[]
for l in t1.splitlines():
    if l.startswith("|") and "---" not in l and "Seedbank" not in l:
        c=pipe(l); sp.append(c)
SRC="Muir, A. M., Vesk, P. A., & Hepworth, G. (2014). Reproductive trajectories over decadal time-spans after fire for eight obligate-seeder shrub species in south-eastern Australia. Australian Journal of Botany, 62, 369-378."
LOC="Dandenong Ranges National Park; Bunyip State Park/Kurth Kiln Regional Park"
PAPER=("Paper-wide: chronosequence (space-for-time) study in open forests of Victoria, sites in two clusters, Dandenong Ranges National Park and Bunyip State Park/Kurth Kiln Regional Park (p. 370); species not assigned to a cluster, so one row for both; "
 "coordinates not stated; long-term mean annual rainfall 1200 mm for both clusters (p. 370); sites 2 to >40 years since last fire, fire type, season and severity not stated; "
 "obligate seeders are species killed by fire with recruitment by seed only (p. 370); modelled times to 80% of maximum flower or seed production are not time for 80% of individuals to flower, so are not in Time to 80% flowering; "
 "juvenile periods in Table 1 are expert estimates (DSE 2010e), not measurements")
rows=[]
for c in sp:
    seedbank,jp,life,full=c
    full=re.sub(r"\*([^*]+)\*",r"\1",full)
    full=re.sub(r"\s*\([^)]*\)","",full)   # authorities in brackets
    toks=full.split()
    g,s=toks[0],toks[1]; sub=""
    for k in ("subsp.","var."):
        if k in toks: i=toks.index(k); sub=" ".join(toks[i:i+2])
    key=f"{g} {s}"
    row4=T4[key]
    n=[f"Table 4, p. 374; Table 1, p. 371"]
    fl=row4[3]; se=row4[4]
    if fl:
        m=re.fullmatch(r"(\d+) \((\d+), (\d+)\)",fl); assert m,fl
        n.append(f"time to 80% of maximum annual flower production (fitted mean, log scale) {m.group(1)} years (95% CI {m.group(2)}-{m.group(3)}), measure differs from Time to 80% flowering")
    else: n.append("time to 80% of maximum flower production not predicted: asymptotes had very large confidence intervals (p. 372)")
    if se:
        m=re.fullmatch(r"(\d+) \((\d+), (\d+)\)",se); assert m,se
        n.append(f"time to 80% of seed production {m.group(1)} years (95% CI {m.group(2)}-{m.group(3)})")
    n.append(f"Table 1 expert estimate of juvenile period (DSE 2010e): {jp}; seedbank {seedbank.lower()}")
    r={"Genus":g,"Species":s,"scientific_name":key,"fire_response categorical_surv1":"obligate","Location_name":LOC,"Rainfall_mm":"1200","Notes":"; ".join(n+[PAPER]),"Source":SRC,"File_name":stem}
    if sub: r["subsp"]=sub
    rows.append(r)
for r in rows: print(r["scientific_name"],r.get("subsp",""),"|",r["Notes"].split("; Paper-wide")[0][:330])
import pickle; pickle.dump(rows,open("muir.pkl","wb"))
E
python3 muir.py

