from common import *
import random, pickle
from collections import defaultdict
stem="nswfrrd_v1.3a_pdfvers_sppdata"
t=md(stem); pg=t.split("<!-- PAGE BREAK -->")
PAPER=("Paper-wide: printout of a species database with no methods text; fire response codes are not defined in the document and are copied as printed; "
 "no unit is stated for Primary juvenile, Secondary juvenile period or Recommended minimum interval, so the time columns are empty; no study site, coordinates, rainfall or fire details are stated")
def rows_of(k):
    return [pipe(l) for l in pg[k].splitlines() if l.startswith("|") and "---" not in l and not l.startswith("| Species")]
HEAD_REG=["Species","Synonym","Family","Fire response","Comments on regeneration","Seed storage","Seed dispersal","Germination cue","NFRR data","Additional fire response data"]
out=[];srcl=[]
allreg=[]
for k in range(1,205,2):
    a=rows_of(k); b=rows_of(k+1)
    vmap=defaultdict(list)
    for y in b: vmap[y[0]].append(y)
    seen=defaultdict(int)
    for x in a: allreg.append((k+1,x))
    dups=defaultdict(list)
    for x in a: dups[x[0]].append(x)
    for x in a:
        name=x[0]; i=seen[name]; seen[name]+=1
        va=vmap[name][i]
        syn,fam,fr,comm=x[1],x[2],x[3],x[4]
        pj,sj,rmi=va[4],va[5],va[6]; dist=va[9]
        toks=name.split(); g=toks[0]; rest=toks[1:]; sub=""; subnote=[]
        for j,tk in enumerate(rest):
            if tk in("subsp.","var.","forma","f."):
                sub=" ".join(rest[j:]); rest=rest[:j]; break
        if sub.startswith("forma"):
